120	func (m *Manager) Start(ctx context.Context) error {
121		m.mu.Lock()
122		defer m.mu.Unlock()
123	
124		if m.running {
125			m.logger.Info("KNIRVHASHER already running")
126			return nil
127		}
128	
129		if m.config.BinaryPath == "" {
130			m.config.BinaryPath = "./knirvhasher"
131		}
132	
133		resolved, err := resolveBinaryPath(m.config.BinaryPath)
134		if err != nil {
135			return fmt.Errorf("KNIRVHASHER binary not found: %w", err)
136		}
137		m.config.BinaryPath = resolved
138	
139		hasherDir := filepath.Dir(m.socketPath)
140		if hasherDir != "." && hasherDir != "/" {
141			if err := os.MkdirAll(hasherDir, 0755); err != nil {
142				return fmt.Errorf("failed to create socket directory: %w", err)
143			}
144		}
145	
146		if _, err := os.Stat(m.socketPath); err == nil {
147			os.Remove(m.socketPath)
148		}
149	
150		m.logger.Info("Starting KNIRVHASHER",
151			zap.String("binary", m.config.BinaryPath),
152			zap.String("socket", m.socketPath))
153	
154		env := os.Environ()
155		env = append(env,
156			fmt.Sprintf("HASHER_SOCKET_PATH=%s", m.socketPath),
157			fmt.Sprintf("HASHER_DATA_PATH=%s", m.config.DataPath),
158		)
159		if m.config.GRPCSocketPath != "" {
160			env = append(env, fmt.Sprintf("HASHER_GRPC_SOCKET_PATH=%s", m.config.GRPCSocketPath))
161		}
162	
163		if appDataDir := os.Getenv("KNIRV_APP_DATA_DIR"); appDataDir != "" {
164			env = append(env, fmt.Sprintf("KNIRV_APP_DATA_DIR=%s", appDataDir))
165		} else if _, err := os.Stat("/var/lib/knirvserver"); err == nil {
166			env = append(env, "KNIRV_APP_DATA_DIR=/var/lib/knirvserver")
167		}
168	
169		if m.config.ArxivEnabled {
170			env = append(env, "DATAMINER_MODE=production", "ARXIV_ENABLED=true")
171		}
172	
173		for k, v := range m.config.EnvOverrides {
174			env = append(env, fmt.Sprintf("%s=%s", k, v))
175		}
176	
177		args := []string{}
178		if m.config.HeadlessMode {
179			socketPerm := fmt.Sprintf("%04o", m.config.SocketPerm)
180			args = append(args,
181				"--headless",
182				fmt.Sprintf("--socket-path=%s", m.socketPath),
183				fmt.Sprintf("--socket-perm=%s", socketPerm),
184			)
185		}
186		// Default pipeline: MAPPER mode via Hugging Face API.
187		// Data-connector (CONNECTION source) only runs after full user onboarding.
188		if m.config.PipelineType == "goat" {
189			args = append(args, "-goat")
190		}
191	
192		m.cmd = exec.Command(m.config.BinaryPath, args...)
193		m.cmd.Env = env
194		if w, ok := m.config.Stdout.(io.Writer); ok {
195			m.cmd.Stdout = w
196		} else {
197			m.cmd.Stdout = os.Stdout
198		}
199		if w, ok := m.config.Stderr.(io.Writer); ok {
200			m.cmd.Stderr = w
201		} else {
202			m.cmd.Stderr = os.Stderr
203		}
204		m.cmd.SysProcAttr = &syscall.SysProcAttr{
205			Setpgid: true,
206		}
207	
208		if err := m.cmd.Start(); err != nil {
209			return fmt.Errorf("failed to start KNIRVHASHER: %w", err)
210		}
211		m.startTime = time.Now()
212		m.logger.Info("KNIRVHASHER subprocess started",
213			zap.Int("pid", m.cmd.Process.Pid))
214	
215		if err := m.waitForSocket(ctx); err != nil {
216			m.cmd.Process.Kill()
217			return fmt.Errorf("socket creation failed: %w", err)
218		}
219	
220		if m.config.HeadlessMode {
221			m.logger.Info("KNIRVHASHER Unix socket ready")
222			// Pipeline is NOT auto-started here.  The user triggers it via the
223			// frontend "Start Training" button, which calls hasherStart → Start()
224			// followed by RunPipeline() on the Manager, which POSTs to the
225			// headless server's /api/v1/pipeline/run endpoint.
226		}
227	
228		m.running = true
229		m.logger.Info("KNIRVHASHER started successfully",
230			zap.String("socket", m.socketPath))
231	
232		return nil
233	}
