235	func resolveBinaryPath(configured string) (string, error) {
236		var candidates []string
237	
238		if envPath := os.Getenv("KNIRV_HASHER_BINARY_PATH"); envPath != "" {
239			candidates = append(candidates, envPath)
240		}
241	
242		if extractedPath, err := ExtractEmbeddedBinary(""); err == nil {
243			candidates = append(candidates, extractedPath)
244		}
245	
246		if exe, err := os.Executable(); err == nil {
247			exeDir := filepath.Dir(exe)
248			candidates = append(candidates,
249				filepath.Join(exeDir, "knirvhasher"),
250				filepath.Join(exeDir, "bin", "knirvhasher"),
251			)
252		}
253	
254		embeddedDir := filepath.Join(getHasherAppDataDir(), "bin")
255		candidates = append(candidates,
256			filepath.Join(embeddedDir, "knirvhasher"),
257			filepath.Join(embeddedDir, "..", "bin", "knirvhasher"),
258		)
259	
260		candidates = append(candidates, configured)
261	
262		dir, _ := os.Getwd()
263		candidates = append(candidates,
264			filepath.Join(dir, "bin", "knirvhasher"),
265			filepath.Join(dir, "..", "bin", "knirvhasher"),
266		)
267	
268		for _, p := range candidates {
269			if _, err := os.Stat(p); err == nil {
270				return p, nil
271			}
272		}
273	
274		return "", fmt.Errorf("binary not found in any candidate location")
275	}
276	
277	func (m *Manager) waitForSocket(ctx context.Context) error {
278		deadline, cancel := context.WithTimeout(ctx, m.config.StartTimeout)
279		defer cancel()
280	
281		ticker := time.NewTicker(500 * time.Millisecond)
282		defer ticker.Stop()
283	
284		for {
285			select {
286			case <-deadline.Done():
287				return fmt.Errorf("timeout waiting for KNIRVHASHER socket at %s", m.socketPath)
288			case <-ticker.C:
289				if _, err := os.Stat(m.socketPath); err == nil {
290					m.logger.Debug("KNIRVHASHER socket created at", zap.String("socket", m.socketPath))
291					return nil
292				}
293			}
294		}
295	}
296	
297	func (m *Manager) Stop(ctx context.Context) error {
298		m.mu.Lock()
299		defer m.mu.Unlock()
300	
301		if !m.running || m.cmd == nil || m.cmd.Process == nil {
302			return nil
303		}
304	
305		m.logger.Info("Stopping KNIRVHASHER")
306	
307		if err := m.cmd.Process.Signal(syscall.SIGTERM); err != nil {
308			m.logger.Warn("Failed to send SIGTERM, forcing kill",
309				zap.Error(err))
310			syscall.Kill(-m.cmd.Process.Pid, syscall.SIGKILL)
311		}
312	
313		done := make(chan error, 1)
314		go func() {
315			done <- m.cmd.Wait()
316		}()
317	
318		select {
319		case err := <-done:
320			m.running = false
321			m.startTime = time.Time{}
322			if err != nil {
323				m.logger.Info("KNIRVHASHER stopped", zap.Error(err))
324			} else {
325				m.logger.Info("KNIRVHASHER stopped gracefully")
326			}
327			return nil
328		case <-time.After(m.config.StopTimeout):
329			m.logger.Warn("Timeout waiting for graceful shutdown, forcing kill")
330			syscall.Kill(-m.cmd.Process.Pid, syscall.SIGKILL)
331			select {
332			case <-done:
333			case <-time.After(2 * time.Second):
334				m.logger.Warn("Wait() did not complete after Kill() — zombie possible")
335			}
336			m.running = false
337			m.startTime = time.Time{}
338			return fmt.Errorf("forced shutdown after timeout")
339		}
340	}
341	
342	func (m *Manager) IsRunning() bool {
343		m.mu.RLock()
344		defer m.mu.RUnlock()
345		return m.running
346	}
347	
348	func (m *Manager) GetSocketPath() string {
349		return m.socketPath
350	}
351	
352	func (m *Manager) GetConfig() *ManagerConfig {
353		return m.config
354	}
355	
356	func (m *Manager) GetPID() int {
357		if m.cmd != nil && m.cmd.Process != nil {
358			return m.cmd.Process.Pid
359		}
360		return 0
361	}
362	
363	func (m *Manager) GetStatus() *HasherStatus {
364		m.mu.RLock()
365		defer m.mu.RUnlock()
366	
367		status := &HasherStatus{
368			Status:     "stopped",
369			Running:    m.running,
370			SocketPath: m.socketPath,
371			Timestamp:  time.Now(),
372		}
373		if m.running {
374			status.Status = "running"
375			if !m.startTime.IsZero() {
376				uptime := time.Since(m.startTime)
377				status.Uptime = uptime.Round(time.Second).String()
378			}
379		}
380	
381		return status
382	}
383	
384	func (m *Manager) triggerPipeline() {
385		client := &http.Client{
386			Timeout: 10 * time.Second,
387			Transport: &http.Transport{
388				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
389					var dialer net.Dialer
390					return dialer.DialContext(ctx, "unix", m.socketPath)
391				},
392			},
393		}
394	
395		pipelineURL := "http://localhost/api/v1/pipeline/run"
396		body := fmt.Sprintf(`{"type":"%s"}`, m.config.PipelineType)
397		req, err := http.NewRequest("POST", pipelineURL, strings.NewReader(body))
398		if err != nil {
399			m.logger.Warn("Failed to create pipeline request", zap.Error(err))
400			return
401		}
402		req.Header.Set("Content-Type", "application/json")
403	
404		resp, err := client.Do(req)
405		if err != nil {
406			m.logger.Warn("Failed to trigger KNIRVHASHER data pipeline",
407				zap.String("socket", m.socketPath), zap.Error(err))
408			return
409		}
410		defer resp.Body.Close()
411	
412		if resp.StatusCode == http.StatusOK || resp.StatusCode == http.StatusAccepted {
413			m.logger.Info("KNIRVHASHER data pipeline triggered successfully",
414				zap.String("socket", m.socketPath),
415				zap.String("pipeline", m.config.PipelineType),
416				zap.Int("status", resp.StatusCode))
417		} else {
418			m.logger.Warn("KNIRVHASHER data pipeline trigger returned unexpected status",
419				zap.String("socket", m.socketPath),
420				zap.Int("status", resp.StatusCode))
421		}
422	}
423	
424	func (m *Manager) RunPipeline(pipelineType string) error {
425		if !m.running {
426			return fmt.Errorf("KNIRVHASHER not running")
427		}
428	
429		client := &http.Client{
430			Timeout: 30 * time.Second,
431			Transport: &http.Transport{
432				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
433				dialer := net.Dialer{}
434				return dialer.DialContext(ctx, "unix", m.socketPath)
435				},
436			},
437		}
438	
439		pipelineURL := "http://localhost/api/v1/pipeline/run"
440		body := fmt.Sprintf(`{"type":"%s"}`, pipelineType)
441		req, err := http.NewRequest("POST", pipelineURL, strings.NewReader(body))
442		if err != nil {
443			return fmt.Errorf("failed to create request: %w", err)
444		}
445		req.Header.Set("Content-Type", "application/json")
446	
447		resp, err := client.Do(req)
448		if err != nil {
449			return fmt.Errorf("failed to trigger pipeline: %w", err)
450		}
451		defer resp.Body.Close()
452	
453		if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusAccepted {
454			return fmt.Errorf("pipeline request failed with status %d", resp.StatusCode)
455		}
456	
457		return nil
458	}
459	
460	func (m *Manager) GetHealth() (bool, error) {
461		if !m.running {
462			return false, fmt.Errorf("KNIRVHASHER not running")
463		}
464	
465		client := &http.Client{
466			Timeout: 5 * time.Second,
467			Transport: &http.Transport{
468				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
469				dialer := net.Dialer{}
470				return dialer.DialContext(ctx, "unix", m.socketPath)
471				},
472			},
473		}
474	
475		resp, err := client.Get("http://localhost/api/v1/health")
476		if err != nil {
477			return false, err
478		}
479		defer resp.Body.Close()
480	
481		return resp.StatusCode == http.StatusOK, nil
482	}
483	
484	func (m *Manager) StopPipeline() error {
485		if !m.running {
486			return fmt.Errorf("KNIRVHASHER not running")
487		}
488	
489		client := &http.Client{
490			Timeout: 10 * time.Second,
491			Transport: &http.Transport{
492				DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
493				dialer := net.Dialer{}
494				return dialer.DialContext(ctx, "unix", m.socketPath)
495				},
496			},
497		}
498	
499		resp, err := client.Post("http://localhost/api/v1/pipeline/stop", "application/json", nil)
500		if err != nil {
501			return fmt.Errorf("failed to stop pipeline: %w", err)
502		}
503		defer resp.Body.Close()
504	
505		return nil
506	}
507	
508	func isSocketReady(socketPath string) bool {
509		conn, err := net.Dial("unix", socketPath)
510		if err != nil {
511			return false
512		}
513		conn.Close()
514		return true
515	}

