569		var frameCount int64
570		var recordCount int64
571		log.Printf("[BATCH] Starting to process %d DocumentRecords...", len(records))
572	
573		for i := range records {
574			record := &records[i]
575	
576			// Check if we should skip this record (already processed)
577			if cpManager != nil && cpManager.ShouldSkipRecord(record.FileName, record.ChunkID, 0) {
578				log.Printf("[BATCH] Skipping already processed record %d/%d: %s (chunk %d)",
579					i+1, len(records), record.FileName, record.ChunkID)
580				recordCount++
581				continue
582			}
583	
584			log.Printf("[BATCH] Processing record %d/%d: %s (chunk %d, content: %d chars)",
585				i+1, len(records), record.FileName, record.ChunkID, len(record.Content))
586	
587			// Convert DocumentRecord to MinedRecord format for processing
588			minedRecord := schema.MinedRecord{
589				FileName:     record.FileName,
590				ChunkID:      int(record.ChunkID),
591				Content:      record.Content,
592				Instruction:  record.Instruction,
593				Input:        record.Input,
594				Output:       record.Output,
595				Tokens:       record.Tokens,
596				TokenOffsets: record.TokenOffsets,
597				POSTags:      record.POSTags,
598				Tenses:       record.Tenses,
599				DepHashes:    record.DepHashes,
600			}
601	
602			if err := processSingleRecordWithSlidingWindow(&minedRecord, &frameCount, tp, tk, ew, frames, config, cpManager); err != nil {
603				return 0, fmt.Errorf("failed to process DocumentRecord %d: %w", i, err)
604			}
605	
606			recordCount++
607			log.Printf("[BATCH] Completed record %d/%d, total frames: %d", i+1, len(records), frameCount)
608	
609			// Update checkpoint every 10 records
610			if cpManager != nil && i%10 == 0 {
611				cpManager.UpdateProgress(record.FileName, record.ChunkID, 0)
612				cpManager.IncrementStats(1, frameCount-cpManager.GetCheckpoint().FramesGenerated)
613				if err := cpManager.Save(); err != nil {
614					log.Printf("⚠️  Failed to save checkpoint: %v", err)
615				}
616			}
617	
618			// Progress logging every 10 records (more frequent)
619			if i%10 == 0 {
620				log.Printf("📊 Processed %d/%d DocumentRecords, generated %d frames...", i, len(records), frameCount)
621			}
622		}
623	
624		log.Printf("📈 Total: %d DocumentRecords processed, %d training frames generated", recordCount, frameCount)
625		return frameCount, nil
626	}
