668	// processJSONLRecords processes JSONL format records
669	func processJSONLRecords(content string, tp *mapper.TensorPacker, tk *tokenizer.Service, ew embeddings.EmbeddingService, frames *[]schema.TrainingFrame, config *Config, cpManager *checkpoint.Manager) (int64, error) {
670		var recordCount, frameCount, fixedCount int64
671		scanner := bufio.NewScanner(strings.NewReader(content))
672		var updatedLines []string
673	
674		for scanner.Scan() {
675			line := strings.TrimSpace(scanner.Text())
676			if line == "" {
677				continue
678			}
679	
680			// Try to parse the JSON record
681			var record schema.MinedRecord
682			err := json.Unmarshal([]byte(line), &record)
683	
684			if err != nil {
685				// Try to fix the JSON
686				fixedJSON := fixJSONString(line)
687				if parseErr := json.Unmarshal([]byte(fixedJSON), &record); parseErr != nil {
688					if recordCount%10 == 0 || recordCount < 10 {
689						log.Printf("⚠️  Skipping unfixable record %d: %v", recordCount, err)
690					}
691					continue
692				}
693	
694				// Use the fixed version for file update
695				updatedLines = append(updatedLines, fixedJSON)
696				fixedCount++
697				if fixedCount <= 10 {
698					log.Printf("🔧 Fixed record %d", recordCount)
699				}
700			} else {
701				updatedLines = append(updatedLines, line)
702			}
703	
704			recordCount++
705	
706			// Check if we should skip this record
707			if cpManager != nil && cpManager.ShouldSkipRecord(record.FileName, int32(record.ChunkID), 0) {
708				log.Printf("[BATCH] Skipping already processed record %d: %s", recordCount, record.FileName)
709				continue
710			}
711	
712			// Process the record with sliding windows
713			if err := processSingleRecordWithSlidingWindow(&record, &frameCount, tp, tk, ew, frames, config, cpManager); err != nil {
714				return 0, fmt.Errorf("failed to process record %d: %w", recordCount, err)
715			}
716	
717			// Update checkpoint every 10 records
718			if cpManager != nil && recordCount%10 == 0 {
719				cpManager.UpdateProgress(record.FileName, int32(record.ChunkID), 0)
720				cpManager.IncrementStats(1, frameCount-cpManager.GetCheckpoint().FramesGenerated)
721				if err := cpManager.Save(); err != nil {
722					log.Printf("⚠️  Failed to save checkpoint: %v", err)
723				}
724			}
725	
726			// Progress logging every 100 records
727			if recordCount%100 == 0 {
728				log.Printf("📊 Processed %d records, generated %d frames (fixed: %d)...", recordCount, frameCount, fixedCount)
729			}
730		}
731	
732		// Update file with fixed content if any records were fixed
733		if fixedCount > 0 {
734			fixedContent := strings.Join(updatedLines, "\n") + "\n"
735			if writeErr := os.WriteFile(config.InputFile, []byte(fixedContent), 0644); writeErr != nil {
736				log.Printf("⚠️  Failed to update fixed file: %v", writeErr)
737			} else {
738				log.Printf("🔧 Updated file with %d fixed records", fixedCount)
739			}
740		}
741	
742		log.Printf("📈 Total: %d records processed, %d training frames generated", recordCount, frameCount)
743		if fixedCount > 0 {
744			log.Printf("🔧 JSON issues fixed and updated: %d records", fixedCount)
745		}
746	
747		return frameCount, nil
748	}
749	
750	func fixJSONContent(content string) (string, bool) {
751		original := content
752		fixed := fixJSONString(content)
753	
754		// Check if JSON array is properly closed
755		trimmed := strings.TrimSpace(fixed)
756		if strings.HasPrefix(trimmed, "[") && !strings.HasSuffix(trimmed, "]") {
757			// Add missing closing bracket
758			fixed = fixed + "\n]"
759		}
760	
761		return fixed, original != fixed
762	}
