926	func processStreamingJSON(jsonFile *os.File, tp *mapper.TensorPacker, tk *tokenizer.Service, ew *embeddings.Service, frames *[]schema.TrainingFrame, config *Config, cpManager *checkpoint.Manager) error {
927		decoder := json.NewDecoder(jsonFile)
928		decoder.DisallowUnknownFields()
929	
930		var recordCount, frameCount, fixedCount int64
931	
932		// Processing Loop
933		log.Printf("🚀 Starting encoding from %s...", config.InputFile)
934	
935		for decoder.More() {
936			var record schema.MinedRecord
937			if err := decoder.Decode(&record); err != nil {
938				// Try to fix JSON errors by reading raw and fixing
939				if jsonErr := fixAndRetryRecord(decoder, &record, config, &fixedCount); jsonErr != nil {
940					if recordCount%10 == 0 || recordCount < 10 {
941						log.Printf("⚠️  Skipping bad record %d: %v", recordCount, jsonErr)
942					}
943					continue
944				}
945			}
946	
947			recordCount++
948	
949			// Process with sliding windows
950			if err := processSingleRecordWithSlidingWindow(&record, &frameCount, tp, tk, ew, frames, config, cpManager); err != nil {
951				return fmt.Errorf("failed to process record %d: %w", recordCount, err)
952			}
953	
954			// Progress logging every 100 records
955			if recordCount%100 == 0 {
956				log.Printf("📊 Processed %d records, generated %d frames (fixed: %d)...", recordCount, frameCount, fixedCount)
957			}
958		}
959	
960		log.Printf("📈 Total: %d records processed, %d training frames generated", recordCount, frameCount)
961		if fixedCount > 0 {
962			log.Printf("🔧 JSON issues fixed: %d records", fixedCount)
963		}
964	
965		return nil
966	}
967	
968	func fixAndRetryRecord(decoder *json.Decoder, record *schema.MinedRecord, config *Config, fixedCount *int64) error {
969		// Read the raw JSON bytes and try to fix
970		var rawRecord map[string]interface{}
971		if err := decoder.Decode(&rawRecord); err != nil {
972			return fmt.Errorf("failed to read raw record: %w", err)
973		}
974	
975		// Convert back to JSON and fix common issues
976		jsonBytes, err := json.Marshal(rawRecord)
977		if err != nil {
978			return fmt.Errorf("failed to marshal raw record: %w", err)
979		}
980	
981		fixedJSON := fixJSONString(string(jsonBytes))
982	
983		// Try to parse the fixed JSON
984		if err := json.Unmarshal([]byte(fixedJSON), record); err != nil {
985			return fmt.Errorf("failed to parse fixed record: %w", err)
986		}
987	
988		*fixedCount++
989		return nil
990	}
