993	func processArrowFile(filePath string, tp *mapper.TensorPacker, tk *tokenizer.Service, ew embeddings.EmbeddingService, frames *[]schema.TrainingFrame, config *Config, cpManager *checkpoint.Manager) (int64, error) {
994		log.Printf("🔄 Attempting Arrow IPC stream processing from: %s", filePath)
