1007		// Write to JSON
1008		file, err := os.Create(filePath)
1009		if err != nil {
1010			return fmt.Errorf("failed to create output file: %w", err)
1011		}
1012		defer file.Close()
1013	
1014		encoder := json.NewEncoder(file)
1015		encoder.SetIndent("", "  ")
1016	
1017		if err := encoder.Encode(frames); err != nil {
1018			return fmt.Errorf("failed to encode JSON: %w", err)
1019		}
1020	
1021		return nil
1022	}
1023	
1024	func fixJSONString(jsonStr string) string {
1025		// Step 1: Fix invalid \x escape sequences by removing them completely
1026		invalidEscapeRegex := regexp.MustCompile(`\\x[0-9a-fA-F]{2}`)
1027		fixed := invalidEscapeRegex.ReplaceAllString(jsonStr, "")
1028	
1029		// Step 2: Remove control characters that break JSON
1030		controlCharRegex := regexp.MustCompile(`[\x00-\x08\x0B\x0C\x0E-\x1F]`)
1031		fixed = controlCharRegex.ReplaceAllString(fixed, "")
1032	
1033		// Step 3: Fix invalid escape sequences
1034		// Handle escaped backslash followed by invalid char FIRST: \\ + invalid -> just invalid
1035		// This matches \\ (escaped backslash) followed by any invalid char
1036		fixed = regexp.MustCompile(`\\\\([^"\\bfnrt/])`).ReplaceAllString(fixed, "$1")
1037	
1038		// Then handle single backslash followed by invalid char: \ + invalid -> just invalid
1039		fixed = regexp.MustCompile(`\\([^"\\bfnrt/])`).ReplaceAllString(fixed, "$1")
1040	
1041		return fixed
1042	}
