272	func (c *Controller) StopDriver(ctx context.Context) error {
273		if c.serverCmd == nil || c.serverCmd.Process == nil {
274			return nil
275		}
276	
277		fmt.Println("Shutting down hasher-host...")
278	
279		if c.apiClient != nil {
280			shutdownURL := c.apiClient.BaseURL + "/api/v1/shutdown"
281			http.Post(shutdownURL, "application/json", nil)
282		}
283	
284		done := make(chan error, 1)
285		go func() {
286			done <- c.serverCmd.Wait()
287		}()
288	
289		select {
290		case <-done:
291			fmt.Println("hasher-host shut down successfully.")
292		case <-time.After(15 * time.Second):
293			fmt.Println("hasher-host shutdown timeout, force killing...")
294			c.serverCmd.Process.Kill()
295		}
296	
297		c.serverCmd = nil
298		c.model.ServerCmd = nil
299		c.model.ServerReady = false
300		c.model.ServerStarting = false
301		c.apiClient = nil
302	
303		return nil
304	}
