709	
710		c.pipelineState.Mu.Lock()
711		c.pipelineState.Cmd = cmd
712		c.pipelineState.Running = true
713		c.pipelineState.Mu.Unlock()
714	
715		go c.streamPipelineOutput(cmd, stdout, stderr, 0, PipelineStage{
716			Name:    "MATHASHER",
717			BinName: "hasher-host",
718			Desc:    "Math verification server",
719		})
720	
721		return nil
722	}
723	
724	func (c *Controller) SendChat(ctx context.Context, message string) (string, error) {
725		if !c.model.ServerReady || c.apiClient == nil {
726			return "", fmt.Errorf("server not ready. Please start hasher-host first")
727		}
728	
729		resp, err := c.apiClient.CallCryptoTransformer(message, nil)
730		if err != nil {
731			return "", err
732		}
733	
734		return resp.Response, nil
735	}
736	
737	func (c *Controller) GetStatus() map[string]interface{} {
738		status := map[string]interface{}{
739			"driver_running": c.model.ServerReady,
740			"server_ready":   c.model.ServerReady,
741			"device_ip":      c.model.DeviceIP,
742			"device_type":    c.model.DeviceType,
743			"uptime":         time.Since(time.Now()).String(),
744		}
745	
746		if c.deployer != nil {
747			devices := c.deployer.GetDevices()
748			status["devices_discovered"] = len(devices)
749		}
750	
751		return status
752	}
753	
754	func (c *Controller) Cleanup() {
755		if c.model.ServerCmd != nil {
756			c.StopDriver(context.Background())
757		}
758	
759		if c.deployer != nil {
760			c.deployer.Cleanup()
761		}
762	
763		c.pipelineState.Mu.Lock()
764		if c.pipelineState.Cmd != nil {
765			c.pipelineState.Cmd.Process.Kill()
766			c.pipelineState.Running = false
767		}
768		c.pipelineState.Mu.Unlock()
769	
770		fmt.Println("Controller cleanup complete")
771	}
772	
773	func buildPipelineStages(pipelineType string) []PipelineStage {
774		trainerStage := PipelineStage{
775			Name:    "data-trainer",
776			BinName: "data-trainer",
777			Args:    []string{"-verbose", "-epochs", "5", "-sequential", "-hash-method", "cuda"},
778			Desc:    "Data Trainer - Neural network training",
779		}
780		// dataConnectorStage is only used by pipelines that pull from KNIRVSERVER
781		// (i.e. CONNECTION source).  Goat/MAPPER mode fetches from Hugging Face
782		// API directly via data-miner and must NOT run the data-connector first.
783		dataConnectorStage := PipelineStage{
784			Name:    "data-connector",
785			BinName: "data-connector",
786			Args:    []string{},
787			Desc:    "Data Connector - Receives gRPC streams from KNIRVSERVER, decrypts chunks, writes raw .md files",
788		}
789	
790		switch pipelineType {
791		case "arxiv":
792			return []PipelineStage{
793				dataConnectorStage,
794				{Name: "data-miner", BinName: "data-miner",
795					Args: []string{"-arxiv-enable"}, Desc: "Data Miner - ArXiv paper mining"},
796				{Name: "data-encoder", BinName: "data-encoder",
797					Args: []string{"-workers", "2"}, Desc: "Data Encoder - Tokenization and embeddings"},
798				trainerStage,
799			}
800		case "demo":
801			return []PipelineStage{
802				dataConnectorStage,
803				{Name: "data-miner", BinName: "data-miner",
804					Args: []string{"-demo"}, Desc: "Data Miner - Generating hello world demo frames"},
805				trainerStage,
806			}
807		default: // "goat" — MAPPER mode: data-miner with -goat reads Hugging Face API directly
808			return []PipelineStage{
809				{Name: "data-miner", BinName: "data-miner",
810					Args: []string{"-goat"}, Desc: "Data Miner (MAPPER) - GOAT dataset via Hugging Face API"},
811				{Name: "data-encoder", BinName: "data-encoder",
812					Args: []string{"-workers", "2"}, Desc: "Data Encoder - Tokenization and embeddings"},
813				trainerStage,
814			}
815		}
816	}
817	
818	
819	func findRunningHasherHost() int {
820		ports := []int{8080, 8081, 8082, 8083, 8084, 8085, 8008, 9000}
821		client := &http.Client{Timeout: 2 * time.Second}
822		for _, port := range ports {
823			resp, err := client.Get(fmt.Sprintf("http://localhost:%d/api/v1/health", port))
824			if err == nil {
825				resp.Body.Close()
826				if resp.StatusCode == 200 {
827					return port
828				}
829			}
830		}
831		return 0
832	}
833	
834	func isHasherHostRunning(port int) bool {
835		client := &http.Client{Timeout: 5 * time.Second}
836		resp, err := client.Get(fmt.Sprintf("http://localhost:%d/api/v1/health", port))
837		if err != nil {
838			return false
839		}
840		defer resp.Body.Close()
841		return resp.StatusCode == 200
842	}
