package app

import (
	"os"
	"path/filepath"
	"runtime"
)

// GetAppDataDir returns the OS-specific application data directory.
// Privileged launches use a system location so sudo does not split data
// between /root and the invoking user's home directory.
func GetAppDataDir() (string, error) {
	var basePath string

	switch runtime.GOOS {
	case "windows":
		// %APPDATA% on Windows
		if appData := os.Getenv("APPDATA"); appData != "" {
			basePath = appData
		} else {
			// Fallback to user profile
			if userProfile := os.Getenv("USERPROFILE"); userProfile != "" {
				basePath = filepath.Join(userProfile, "AppData", "Roaming")
			} else {
				// Ultimate fallback
				basePath = filepath.Join(os.TempDir(), "knirvserver", "data")
			}
		}
	case "darwin":
		// ~/Library/Application Support on macOS
		if home := os.Getenv("HOME"); home != "" {
			basePath = filepath.Join(home, "Library", "Application Support")
		} else {
			basePath = os.TempDir()
		}
	default: // linux, unix, etc.
		// KNIRV_APP_DATA_DIR takes highest precedence
		if explicit := os.Getenv("KNIRV_APP_DATA_DIR"); explicit != "" {
			if err := os.MkdirAll(explicit, 0755); err == nil {
				return filepath.Join(explicit, "hasher", "data"), nil
			}
		}
		// System location
		if err := os.MkdirAll("/var/lib/knirvserver/hasher/data", 0755); err == nil {
			return "/var/lib/knirvserver/hasher/data", nil
		}
		// ~/.local/share on XDG Base Directory Specification
		if home := os.Getenv("HOME"); home != "" {
			if xdgData := os.Getenv("XDG_DATA_HOME"); xdgData != "" {
				basePath = xdgData
			} else {
				basePath = filepath.Join(home, ".local", "share")
			}
		} else {
			basePath = os.TempDir()
		}
	}

	appDir := filepath.Join(basePath, "knirvserver", "hasher", "data")

	// Ensure the directory exists
	if err := os.MkdirAll(appDir, 0755); err != nil {
		return "", err
	}

	return appDir, nil
}

// SetupDataDirectories creates all necessary data directories within the app data directory
func SetupDataDirectories(appDataDir string) (map[string]string, error) {
	dirs := map[string]string{
		"checkpoints": filepath.Join(appDataDir, "checkpoints"),
		"papers":      filepath.Join(appDataDir, "papers"),
		"json":        filepath.Join(appDataDir, "json"),
		"documents":   filepath.Join(appDataDir, "documents"),
		"temp":        filepath.Join(appDataDir, "temp"),
	}

	// Create all directories
	for _, dir := range dirs {
		if err := os.MkdirAll(dir, 0755); err != nil {
			return nil, err
		}
	}

	return dirs, nil
}

package app

import (
	"context"
	"fmt"
	"log"
	"os"
	"path/filepath"

	"data-miner/internal/cleaner"
	"data-miner/internal/normalizer"
	"data-miner/internal/writer"
)

// MinerApp reads raw .md files written by 0_DATA_CONNECTOR, cleans and
// normalises each document via the SpaCy NLP pipeline, then writes the output
// as .arrow IPC files into processedDir for consumption by 2_DATA_ENCODER.
type MinerApp struct {
	rawDir     string
	normalizer *normalizer.SecurityNormalizer
	cleaner    *cleaner.Cleaner
	writer     *writer.ArrowWriter
}

// NewMinerApp constructs a MinerApp.
//   - rawDir      – directory containing raw .md files from 0_DATA_CONNECTOR
//   - processedDir – directory to write processed .arrow files
func NewMinerApp(rawDir, processedDir string) *MinerApp {
	return &MinerApp{
		rawDir:     rawDir,
		normalizer: normalizer.NewSecurityNormalizer(),
		cleaner:    cleaner.New(),
		writer:     writer.NewArrowWriter(processedDir),
	}
}

// Run iterates over all .md files in rawDir, runs each through the
// cleaner → normaliser chain, and writes the resulting SecurityRecords as a
// .arrow IPC file to processedDir.
func (m *MinerApp) Run(ctx context.Context) error {
	pattern := filepath.Join(m.rawDir, "*.md")
	files, err := filepath.Glob(pattern)
	if err != nil {
		return fmt.Errorf("glob %s: %w", pattern, err)
	}

	for _, path := range files {
		if err := ctx.Err(); err != nil {
			return err
		}

		docID := filepath.Base(path)

		raw, err := os.ReadFile(path)
		if err != nil {
			log.Printf("miner: read %s: %v", docID, err)
			continue
		}

		cleaned, err := m.cleaner.CleanMarkdown(string(raw))
		if err != nil {
			log.Printf("miner: cleaner skip %s: %v", docID, err)
			continue
		}

		records, err := m.normalizer.Process(cleaned)
		if err != nil {
			log.Printf("miner: normalizer skip %s: %v", docID, err)
			continue
		}

		if err := m.writer.WriteBatch(docID, records); err != nil {
			log.Printf("miner: arrow writer %s: %v", docID, err)
		}
	}
	return nil
}

