19		MaxRetries = 3
20		// CloudflareWorkersBGE is the BGE-Base model identifier for Cloudflare Workers AI
21		CloudflareWorkersBGE = "@cf/baai/bge-base-en-v1.5"
22	)
23	
24	// EmbeddingService is the interface that all embedding services must implement
25	type EmbeddingService interface {
26		GetEmbedding(text string) ([]float32, error)
27		GetBatchEmbeddings(texts []string) ([][]float32, error)
28		GetBatchSize() int
29		ValidateEndpoint() error
30		SetTimeout(timeout interface{})
31	}
32	
33	// Service handles embedding generation via Cloudflare Workers AI API or Ollama
34	type Service struct {
35		baseURL     string
36		httpClient  *http.Client
37		batchSize   int
38		model       string
39		ollamaHost  string
40		ollamaModel string
41	}
42	
43	// CloudflareWorkersRequest represents the Cloudflare Workers AI API request structure
44	type CloudflareWorkersRequest struct {
45		Texts []string `json:"texts"`
46	}
47	
48	// CloudflareWorkersResponse represents the Cloudflare Workers AI API response structure
49	type CloudflareWorkersResponse struct {
50		Success    bool        `json:"success"`
51		Timestamp  string      `json:"timestamp"`
52		Model      string      `json:"model"`
53		Embeddings [][]float32 `json:"embeddings"`
54		Count      int         `json:"count"`
55	}
56	
57	// New creates a new embeddings service based on EMBEDDING_BACKEND config
58	func New() EmbeddingService {
59		config.LoadEnv()
60		backend := config.GetEmbeddingBackend()
61	
62		switch backend {
63		case "deterministic":
64			log.Println("Using deterministic (local) embeddings")
65			return NewDeterministicService()
66		case "cloudflare":
67			log.Println("Using Cloudflare Workers AI embeddings")
68			return newCloudflareService()
69		case "ollama":
70			log.Println("Using Ollama embeddings")
71			return newOllamaService()
72		default:
73			log.Printf("Unknown EMBEDDING_BACKEND: %s, defaulting to deterministic", backend)
74			return NewDeterministicService()
75		}
76	}
77	
78	// NewWithBatchSize creates a new embeddings service with custom batch size
79	func NewWithBatchSize(batchSize int) EmbeddingService {
80		config.LoadEnv()
81		backend := config.GetEmbeddingBackend()
82	
83		switch backend {
84		case "deterministic":
85			svc := NewDeterministicService()
86			svc.batchSize = batchSize
87			return svc
88		case "cloudflare":
89			return newCloudflareServiceWithBatchSize(batchSize)
90		case "ollama":
91			return newOllamaServiceWithBatchSize(batchSize)
92		default:
93			svc := NewDeterministicService()
94			svc.batchSize = batchSize
95			return svc
96		}
97	}
98	
99	func newCloudflareService() *Service {
100		endpoint := config.GetCloudflareEndpoint()
101		svc := &Service{
102			baseURL:     endpoint,
103			httpClient:  &http.Client{Timeout: 30 * time.Second},
104			batchSize:   DefaultBatchSize,
105			model:       CloudflareWorkersBGE,
106			ollamaHost:  "http://localhost:11434/api/embeddings",
107			ollamaModel: "nomic-embed-text",
108		}
109	
110		if endpoint != "" {
111			if err := svc.ValidateEndpoint(); err != nil {
112				log.Fatalf("❌ Embeddings endpoint validation failed: %v", err)
113			}
114			log.Printf("✅ Embeddings endpoint validated: %s", endpoint)
115		}
116	
117		return svc
118	}
119	
120	func newOllamaService() *Service {
121		return &Service{
122			baseURL:     "",
123			httpClient:  &http.Client{Timeout: 120 * time.Second},
124			batchSize:   DefaultBatchSize,
125			model:       CloudflareWorkersBGE,
