2	// Package embedded provides embedded hasher binaries that are extracted at runtime
3	package embedded
4	
5	import (
6		"embed"
7		"fmt"
8		"io/fs"
9		"os"
10		"path/filepath"
11		"runtime"
12		"strings"
13	)
14	
15	// NOTE: Binaries are optionally embedded at build time.
16	// Build the binaries first using:
17	//   make build-host         # For hasher-host (native)
18	//
19	// The Makefile should place binaries in: internal/cli/embedded/bin/
20	// If binaries aren't present, the CLI will look for pre-compiled binaries
21	// in the app data directory or prompt to compile them.
22	
23	//go:embed all:bin/*
24	var embeddedBinaries embed.FS
25	
26	// BinaryInfo contains metadata about an embedded binary
27	type BinaryInfo struct {
28		Name        string // Binary name (e.g., "hasher-host")
29		Description string // Human-readable description
30		TargetOS    string // Target OS (linux, darwin, windows)
31		TargetArch  string // Target architecture (amd64, mips, arm64)
32		Embedded    bool   // Whether binary is embedded
33	}
34	
35	// AvailableBinaries lists all binaries that should be embedded
36	var AvailableBinaries = []BinaryInfo{
37		{
38			Name:        "hasher-host",
39			Description: "Hasher orchestrator for Native OS",
40			TargetOS:    "linux",
41			TargetArch:  "amd64",
42		},
43		{
44			Name:        "data-connector",
45			Description: "Data Connector - Server connection and knirvbase interface pipeline",
46			TargetOS:    "linux",
47			TargetArch:  "amd64",
48		},
49		{
50			Name:        "data-miner",
51			Description: "Data Miner - Document structuring and PDF processing pipeline",
52			TargetOS:    "linux",
53			TargetArch:  "amd64",
54		},
55		{
56			Name:        "data-encoder",
57			Description: "Data Encoder - Tokenization and embedding generation pipeline",
58			TargetOS:    "linux",
59			TargetArch:  "amd64",
60		},
61		{
62			Name:        "data-trainer",
63			Description: "Data Trainer - Model training and neural network optimization pipeline",
64			TargetOS:    "linux",
65			TargetArch:  "amd64",
66		},
67	}
68	
69	// GetAppDataDir returns the OS-specific application data directory.
70	// Privileged launches use a system location so sudo does not split data
71	// between /root and the invoking user's home directory.
72	func GetAppDataDir() (string, error) {
73		// KNIRV_APP_DATA_DIR env var takes highest precedence (set by KNIRVSERVER
74		// when it spawns the hasher subprocess so both use the same root).
75		if explicit := strings.TrimSpace(os.Getenv("KNIRV_APP_DATA_DIR")); explicit != "" {
76			if err := os.MkdirAll(explicit, 0755); err != nil {
77				return "", fmt.Errorf("failed to create app data directory %s: %w", explicit, err)
78			}
79			return explicit, nil
80		}
81	
82		switch runtime.GOOS {
83		case "linux":
84			// System location — works under sudo.
85			if err := os.MkdirAll("/var/lib/knirvserver", 0755); err == nil {
86				return "/var/lib/knirvserver", nil
87			}
88			// XDG_DATA_HOME or ~/.local/share
89			if xdg := os.Getenv("XDG_DATA_HOME"); xdg != "" {
90				return filepath.Join(xdg, "knirvserver"), nil
91			}
92			home, err := os.UserHomeDir()
93			if err != nil {
94				return "", fmt.Errorf("failed to get home directory: %w", err)
95			}
96			return filepath.Join(home, ".local", "share", "knirvserver"), nil
97		case "darwin":
98			home, err := os.UserHomeDir()
99			if err != nil {
100				return "", fmt.Errorf("failed to get home directory: %w", err)
101			}
102			return filepath.Join(home, "Library", "Application Support", "knirvserver"), nil
103		case "windows":
104			baseDir := os.Getenv("LOCALAPPDATA")
105			if baseDir == "" {
106				home, err := os.UserHomeDir()
107				if err != nil {
108					return "", fmt.Errorf("failed to get home directory: %w", err)
109				}
110				baseDir = filepath.Join(home, "AppData", "Local")
111			}
112			return filepath.Join(baseDir, "knirvserver"), nil
113		default:
114			home, err := os.UserHomeDir()
115			if err != nil {
116				return "", fmt.Errorf("failed to get home directory: %w", err)
117			}
118			return filepath.Join(home, ".local", "share", "knirvserver"), nil
119		}
120	}
121	
122	// GetBinDir returns the directory where binaries should be extracted
123	func GetBinDir() (string, error) {
124		appDir, err := GetAppDataDir()
125		if err != nil {
126			return "", err
127		}
