1	package simulator
2	
3	import (
4		"encoding/binary"
5		"fmt"
6		"os/exec"
7		"strings"
8		"sync"
9	
10		"knirvhasher/pkg/hashing/core"
11		"knirvhasher/pkg/hashing/methods/cuda"
12		"knirvhasher/pkg/hashing/methods/software"
13	)
14	
15	// HasherWrapper implements the HashSimulator interface using hasher's HashMethod
16	// This replaces the internal vhasher simulator with the production-grade hasher module
17	type HasherWrapper struct {
18		hashMethod core.HashMethod
19		config     *SimulatorConfig
20		cache      map[string]uint32
21		cacheMutex sync.RWMutex
22		isRunning  bool
23		mutex      sync.RWMutex
24		methodType string // "auto", "software", "cuda"
25	}
26	
27	// NewHasherWrapper creates a new HashSimulator wrapper using hasher's HashMethod
28	// It defaults to software implementation if no hardware is available
29	func NewHasherWrapper(config *SimulatorConfig) *HasherWrapper {
30		if config == nil {
31			config = &SimulatorConfig{
32				DeviceType:     "software",
33				MaxConcurrency: 100,
34				TargetHashRate: 500000000,
35				CacheSize:      10000,
36				GPUDevice:      0,
37				Timeout:        30,
38			}
39		}
40	
41		return &HasherWrapper{
42			config:    config,
43			cache:     make(map[string]uint32),
44			isRunning: false,
45		}
46	}
47	
48	// Initialize sets up the HashMethod based on configuration
49	func (h *HasherWrapper) Initialize(config *SimulatorConfig) error {
50		h.mutex.Lock()
51		defer h.mutex.Unlock()
52	
53		if config != nil {
54			h.config = config
55			// Check if method type is specified in DeviceType
56			if strings.Contains(config.DeviceType, "software") {
57				h.methodType = "software"
58			} else if strings.Contains(config.DeviceType, "cuda") {
59				h.methodType = "cuda"
60			} else {
61				h.methodType = "auto"
62			}
63		}
64	
65		// Initialize hash method based on type
66		if h.hashMethod == nil {
67			var err error
68			h.hashMethod, err = h.createHashMethod()
69			if err != nil {
70				return fmt.Errorf("failed to create hash method: %w", err)
71			}
72	
73			if err := h.hashMethod.Initialize(); err != nil {
74				return fmt.Errorf("failed to initialize hash method: %w", err)
75			}
76			fmt.Printf("[SIM] Using hash method: %s\n", h.hashMethod.Name())
77		}
78	
79		h.isRunning = true
80		return nil
81	}
82	
83	// createHashMethod creates the appropriate hash method based on configuration
84	func (h *HasherWrapper) createHashMethod() (core.HashMethod, error) {
85		switch h.methodType {
86		case "cuda":
87			// Directly create CUDA method
88			cudaMethod := cuda.NewCudaMethod()
89			if cudaMethod.IsAvailable() {
90				return cudaMethod, nil
91			}
92			// Fall back to software if CUDA not available
93			return software.NewSoftwareMethod(), nil
94	
95		case "software":
96			return software.NewSoftwareMethod(), nil
97	
98		case "auto":
99			// Auto-detect: try CUDA first, then software
100			if h.isCUDAAvailable() {
101				cudaMethod := cuda.NewCudaMethod()
102				if cudaMethod.IsAvailable() {
103					return cudaMethod, nil
104				}
105			}
106			return software.NewSoftwareMethod(), nil
107	
108		default:
109			return software.NewSoftwareMethod(), nil
110		}
111	}
112	
113	// isCUDAAvailable checks if CUDA is available on the system
114	func (h *HasherWrapper) isCUDAAvailable() bool {
115		cmd := exec.Command("nvidia-smi")
116		err := cmd.Run()
117		return err == nil
118	}
119	
120	// SetHashMethod allows injection of a specific HashMethod (e.g., ASIC, CUDA)
121	func (h *HasherWrapper) SetHashMethod(method core.HashMethod) {
122		h.mutex.Lock()
123		defer h.mutex.Unlock()
124		h.hashMethod = method
125	}
126	
127	// SetMethodType sets the hash method type (auto, software, cuda)
128	func (h *HasherWrapper) SetMethodType(methodType string) {
129		h.mutex.Lock()
130		defer h.mutex.Unlock()
131		h.methodType = methodType
132	}
133	
134	// Shutdown cleans up the HashMethod
135	func (h *HasherWrapper) Shutdown() error {
136		h.mutex.Lock()
137		defer h.mutex.Unlock()
138	
139		h.isRunning = false
140	
141		if h.hashMethod != nil {
142			if err := h.hashMethod.Shutdown(); err != nil {
143				return fmt.Errorf("failed to shutdown hash method: %w", err)
144			}
145		}
146	
147		h.cacheMutex.Lock()
148		h.cache = make(map[string]uint32)
149		h.cacheMutex.Unlock()
150	
151		return nil
152	}
153	
154	// SimulateHash performs deterministic hashing using the HashMethod
155	// Maps to: SHA256(seed || pass) with caching
156	func (h *HasherWrapper) SimulateHash(seed []byte, pass int) (uint32, error) {
157		if !h.isRunning {
158			return 0, fmt.Errorf("simulator is not running")
159		}
160	
161		if h.hashMethod == nil {
162			return 0, fmt.Errorf("hash method not initialized")
163		}
164	
165		// Create cache key
166		cacheKey := fmt.Sprintf("%x_%d", seed, pass)
167	
168		// Check cache
169		h.cacheMutex.RLock()
170		if cached, exists := h.cache[cacheKey]; exists {
171			h.cacheMutex.RUnlock()
172			return cached, nil
173		}
174		h.cacheMutex.RUnlock()
175	
176		// Combine seed with pass for deterministic hashing
177		data := make([]byte, len(seed)+4)
178		copy(data, seed)
179		binary.LittleEndian.PutUint32(data[len(seed):], uint32(pass))
180	
181		// Use HashMethod for computation
182		hash, err := h.hashMethod.ComputeHash(data)
183		if err != nil {
184			return 0, fmt.Errorf("hash computation failed: %w", err)
185		}
186	
187		// Extract first 4 bytes as uint32 result (Big-Endian for simulator compatibility)
188		result := binary.BigEndian.Uint32(hash[:4])
189	
190		// Cache result
191		if len(h.cache) < h.config.CacheSize {
192			h.cacheMutex.Lock()
193			h.cache[cacheKey] = result
194			h.cacheMutex.Unlock()
195		}
196	
197		return result, nil
198	}
199	
200	// SimulateBitcoinHeader returns first 4 bytes of Double-SHA256 as uint32
201	func (h *HasherWrapper) SimulateBitcoinHeader(header []byte) (uint32, error) {
202		if !h.isRunning {
203			return 0, fmt.Errorf("simulator is not running")
204		}
205	
206		if h.hashMethod == nil {
207			return 0, fmt.Errorf("hash method not initialized")
208		}
209	
210		// Use MineHeader with a 0-0 range to just get the hash of the current header
211		// or better, if the hashMethod supports a direct double-hash.
212		// Most HashMethods implement double-hash internally for MineHeader.
213		// But core.HashMethod doesn't have a direct "ComputeDoubleHash" exposed.
214		// It has ComputeHash.
215	
216		hash1, err := h.hashMethod.ComputeHash(header)
217		if err != nil {
218			return 0, err
219		}
220	
221		hash2, err := h.hashMethod.ComputeHash(hash1[:])
222		if err != nil {
223			return 0, err
224		}
225	
226		return binary.BigEndian.Uint32(hash2[:4]), nil
227	}
228	
