605	func (c *Controller) streamPipelineOutput(cmd *exec.Cmd, stdout, stderr io.ReadCloser, stageIndex int, stage PipelineStage) {
606		go func() {
607			defer stdout.Close()
608			scanner := bufio.NewScanner(stdout)
609			for scanner.Scan() {
610				line := strings.TrimSpace(scanner.Text())
611				if line != "" {
612					if len(line) > 150 {
613						line = line[:147] + "..."
614					}
615					prefixed := fmt.Sprintf("[%s] [%s] %s", time.Now().Format("15:04:05"), stage.Name, line)
616					// Emit to the parent process stdout so backend_server's SubprocessWriter captures it
617					fmt.Fprintln(os.Stdout, prefixed)
618					logMsg := fmt.Sprintf("[%s] %s", time.Now().Format("15:04:05"), line)
619					c.pipelineLogChan <- PipelineLogMsg{
620						Log:        logMsg,
621						StageIndex: stageIndex,
622						Stage:      stage.Name,
623					}
624				}
625			}
626		}()
627	
628		go func() {
629			defer stderr.Close()
630			scanner := bufio.NewScanner(stderr)
631			for scanner.Scan() {
632				line := strings.TrimSpace(scanner.Text())
633				if line != "" {
634					if len(line) > 150 {
635						line = line[:147] + "..."
636					}
637					prefixed := fmt.Sprintf("[%s] [%s] [stderr] %s", time.Now().Format("15:04:05"), stage.Name, line)
638					// Emit to the parent process stderr so backend_server's SubprocessWriter captures it
639					fmt.Fprintln(os.Stderr, prefixed)
640					logMsg := fmt.Sprintf("[%s] [stderr] %s", time.Now().Format("15:04:05"), line)
641					c.pipelineLogChan <- PipelineLogMsg{
642						Log:        logMsg,
643						StageIndex: stageIndex,
644						Stage:      stage.Name,
645					}
646				}
647			}
648		}()
649	}
