782	func buildPipelineStages(pipelineType string) []PipelineStage {
783		trainerStage := PipelineStage{
784			Name:    "data-trainer",
785			BinName: "data-trainer",
786			Args:    []string{"-verbose", "-epochs", "5", "-sequential", "-hash-method", "cuda"},
787			Desc:    "Data Trainer - Neural network training",
788		}
789		// dataConnectorStage is only used by pipelines that pull from KNIRVSERVER
790		// (i.e. CONNECTION source).  Goat/MAPPER mode fetches from Hugging Face
791		// API directly via data-miner and must NOT run the data-connector first.
792		dataConnectorStage := PipelineStage{
793			Name:    "data-connector",
794			BinName: "data-connector",
795			Args:    []string{},
796			Desc:    "Data Connector - Receives gRPC streams from KNIRVSERVER, decrypts chunks, writes raw .md files",
797		}
798	
799		switch pipelineType {
800		case "arxiv":
801			return []PipelineStage{
802				dataConnectorStage,
803				{Name: "data-miner", BinName: "data-miner",
804					Args: []string{"-arxiv-enable"}, Desc: "Data Miner - ArXiv paper mining"},
805				{Name: "data-encoder", BinName: "data-encoder",
806					Args: []string{"-workers", "2"}, Desc: "Data Encoder - Tokenization and embeddings"},
807				trainerStage,
808			}
809		case "demo":
810			return []PipelineStage{
811				dataConnectorStage,
812				{Name: "data-miner", BinName: "data-miner",
813					Args: []string{"-demo"}, Desc: "Data Miner - Generating hello world demo frames"},
814				trainerStage,
815			}
816		default: // "goat" — MAPPER mode: data-miner with -goat reads Hugging Face API directly
817			return []PipelineStage{
818				{Name: "data-miner", BinName: "data-miner",
819					Args: []string{"-goat"}, Desc: "Data Miner (MAPPER) - GOAT dataset via Hugging Face API"},
820				{Name: "data-encoder", BinName: "data-encoder",
821					Args: []string{"-workers", "2"}, Desc: "Data Encoder - Tokenization and embeddings"},
822				trainerStage,
823			}
824		}
825	}
