}

func (c *Controller) ProvisionASIC(ctx context.Context, deviceIP string) error {
	if c.deployer == nil {
		return fmt.Errorf("deployer not initialized")
	}

	if deviceIP != "" {
		if err := c.deployer.SelectDeviceByIP(deviceIP); err != nil {
			return err
		}
	}

