func (c *Controller) TroubleshootASIC(ctx context.Context) error {
	if c.deployer == nil {
		return fmt.Errorf("deployer not initialized")
	}

	device := c.deployer.GetActiveDevice()
	if device == nil {
		return fmt.Errorf("no device selected - run Discovery first")
	}

