1	package main
2	
3	import (
4		"context"
5		"log"
6		"os"
7		"strings"
8		"time"
9	
10		writer "data-connector/internal/writer"
11		"github.com/knirvcorp/knirvbase/pkg/knirvbase"
12		"google.golang.org/grpc"
13		"google.golang.org/grpc/credentials/insecure"
14		"gopkg.in/yaml.v3"
15		hasherpb "knirvhasher/proto/hasher/training/v1"
16	)
17	
18	type Config struct {
19		KNIRVSERVERAddr string      `yaml:"knirvserver_addr"`
20		KNIRVBASE       KNIRVConfig `yaml:"knirvbase"`
21		PollInterval    string      `yaml:"poll_interval"`
22	}
23	
24	type KNIRVConfig struct {
25		DataDir string `yaml:"data_dir"`
26	}
27	
28	func main() {
29		config := LoadConfig()
30	
31		// Open the single shared KNIRVBASE instance for the whole pipeline.
32		db, err := knirvbase.New(context.Background(), knirvbase.Options{DataDir: config.KNIRVBASE.DataDir})
33		if err != nil {
34			log.Fatalf("open knirvbase: %v", err)
35		}
36		defer db.Shutdown()
37	
38		collection := db.Collection("connector_raw")
39		w := writer.NewMDWriter(collection)
40	
41		// Connect to KNIRVSERVER gRPC server
42		conn, err := grpc.NewClient(config.KNIRVSERVERAddr, grpc.WithTransportCredentials(insecure.NewCredentials()))
43		if err != nil {
44			log.Fatalf("connect to knirvserver: %v", err)
45		}
46		defer conn.Close()
47	
48		client := hasherpb.NewHasherTrainingServiceClient(conn)
49	
50		pollInterval, _ := time.ParseDuration(config.PollInterval)
51		if pollInterval == 0 {
52			pollInterval = 1 * time.Hour
53		}
54	
55		log.Printf("0_DATA_CONNECTOR: Connected to KNIRVSERVER at %s, polling every %s", config.KNIRVSERVERAddr, pollInterval)
56	
57		ticker := time.NewTicker(pollInterval)
58		defer ticker.Stop()
59	
60		for {
61			exportData(client, w)
62			<-ticker.C
63		}
64	}
65	
66	func exportData(client hasherpb.HasherTrainingServiceClient, w *writer.MDWriter) {
67		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
68		defer cancel()
69	
70		stream, err := client.ExportSecurityData(ctx, &hasherpb.ExportRequest{
71			OrgId:    "default",
72			UserId:    "",
73			DataType: hasherpb.DataType_ALL,
74			Encrypted: true,
75		})
76		if err != nil {
77			log.Printf("start export: %v", err)
78			return
79		}
80	
81		for {
82			chunk, err := stream.Recv()
83			if err != nil {
84				if err.Error() != "EOF" {
85					log.Printf("receive chunk: %v", err)
86				}
87				break
88			}
89	
90			if err := w.WriteChunk(chunk); err != nil {
91				log.Printf("write chunk %s: %v", chunk.ChunkId, err)
92			}
93		}
94	
95		log.Printf("export completed")
96	}
97	
98	func LoadConfig() *Config {
99		cfg := &Config{
100			KNIRVSERVERAddr: "localhost:50051",
101			KNIRVBASE:       KNIRVConfig{DataDir: "./data"},
102			PollInterval:    "1h",
103		}
104	
105		data, err := os.ReadFile("config/connector.yaml")
106		if err == nil {
107			if err := yaml.Unmarshal(data, cfg); err != nil {
108				log.Printf("Warning: failed to parse config: %v", err)
109			}
110		}
111	
112		// Environment variable overrides
113		if addr := os.Getenv("HASHER_SOCKET_PATH"); addr != "" {
114			// If provided as a raw path, prefix with unix:// for gRPC
115			if !strings.HasPrefix(addr, "unix://") && !strings.HasPrefix(addr, "passthrough://") {
116				cfg.KNIRVSERVERAddr = "unix://" + addr
117			} else {
118				cfg.KNIRVSERVERAddr = addr
119			}
120		} else if addr := os.Getenv("KNIRVSERVER_ADDR"); addr != "" {
121			cfg.KNIRVSERVERAddr = addr
122		}
123	
124		if dataDir := os.Getenv("KNIRVBASE_DATA_DIR"); dataDir != "" {
125			cfg.KNIRVBASE.DataDir = dataDir
126		}
127	
128		return cfg
129	}
