package main

import (
	"context"
	"log"
	"os"
	"strings"
	"time"

	writer "data-connector/internal/writer"
	"github.com/knirvcorp/knirvbase/pkg/knirvbase"
	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"
