73	func detectPlatform() (*BuildConfig, error) {
74		config := &BuildConfig{
75			OS:   runtime.GOOS,
76			Arch: runtime.GOARCH,
77		}
78	
79		switch runtime.GOOS {
80		case "linux":
81			config.SharedExt = "so"
82			config.ObjectExt = "o"
83			config.CC = detectCompiler([]string{"gcc", "clang", "cc"})
84			config.CXX = detectCompiler([]string{"g++", "clang++", "c++"})
85			config.InstallNameFlag = "" // Linux doesn't need install name
86			config.PkgConfigCmd = []string{"pkg-config", "python3-embed"}
87	
88		case "darwin":
89	
90			config.SharedExt = "dylib"
91			config.ObjectExt = "o"
92			config.CC = detectCompiler([]string{"clang", "gcc", "cc"})
93			config.CXX = detectCompiler([]string{"clang++", "g++", "c++"})
94			config.InstallNameFlag = "-install_name"
95			config.PkgConfigCmd = []string{"pkg-config", "python3"}
96	
97		case "windows":
98			config.SharedExt = "dll"
99			config.ObjectExt = "obj"
100			config.CC = detectCompiler([]string{"gcc", "clang", "cl"})
101			config.CXX = detectCompiler([]string{"g++", "clang++", "cl"})
102			config.InstallNameFlag = "" // Windows doesn't need install name
103			config.PkgConfigCmd = []string{"pkg-config", "python3"}
104	
105		default:
106			return nil, fmt.Errorf("unsupported operating system: %s", runtime.GOOS)
107		}
