128	func detectPythonConfig() string {
129		// On macOS, prefer python-config to avoid version mismatches
130		if runtime.GOOS == "darwin" {
131			pythonConfigs := []string{"python3-config", "python-config"}
132			for _, cmd := range pythonConfigs {
133				if _, err := exec.LookPath(cmd); err == nil {
134					return cmd
135				}
136			}
137		}
138	
139		// Try pkg-config (most portable on Linux)
140		if _, err := exec.LookPath("pkg-config"); err == nil {
141			if exec.Command("pkg-config", "--exists", "python3-embed").Run() == nil {
142				return "pkg-config"
143			}
144			if exec.Command("pkg-config", "--exists", "python3").Run() == nil {
