146			}
147		}
148	
149		// Fallback to python-config
150		pythonConfigs := []string{"python3-config", "python-config"}
151		for _, cmd := range pythonConfigs {
152			if _, err := exec.LookPath(cmd); err == nil {
153				return cmd
154			}
155		}
156	
157		return "python3-config" // Default fallback
158	}
