160	func validateDependencies(config *BuildConfig) error {
161		fmt.Printf("🔍 Validating dependencies...\n")
162	
163		// Check C++ compiler
164		if _, err := exec.LookPath(config.CXX); err != nil {
165			return fmt.Errorf("C++ compiler not found: %s. Please install build tools", config.CXX)
