extern "C" {

int spacy_init(const char* model_name) {
    if (!model_name || strlen(model_name) == 0) {
        std::cerr << "Error: model_name is null or empty" << std::endl;
        return -1;
    }

    // Initialize Python if needed
    {
        std::lock_guard<std::mutex> lock(g_init_mutex);
        if (!g_python_initialized) {
            Py_Initialize();

            // Save the main thread state and release GIL
            // PyEval_InitThreads() is automatic in Python 3.7+
            g_main_thread_state = PyEval_SaveThread();
            g_python_initialized = true;
        }
    }

    try {
        // Ensure GIL is held for this thread
        ScopedGIL gil;

        // Import spacy if not already done
        if (!g_spacy_module) {
            // Setup Python path
            PyObject* sys = PyImport_ImportModule("sys");
            if (sys) {
                PyObject* path = PyObject_GetAttrString(sys, "path");
                if (path) {
                    PyList_Append(path, PyUnicode_FromString("."));
                    // Add user site-packages so user-installed spacy is found
                    PyObject* site = PyImport_ImportModule("site");
                    if (site) {
                        PyObject* userSite = PyObject_CallMethod(site, "getusersitepackages", NULL);
                        if (userSite) {
                            PyList_Append(path, userSite);
                            // Also use addsitedir to process .pth files (handles deps)
                            PyObject* result = PyObject_CallMethod(site, "addsitedir", "O", userSite);
                            Py_XDECREF(result);
                            Py_DECREF(userSite);
                        }
                        Py_DECREF(site);
                    }
                    Py_DECREF(path);
                }
                Py_DECREF(sys);
            }

            g_spacy_module = PyImport_ImportModule("spacy");
            if (!g_spacy_module) {
                PyErr_Print();
                return -1;
            }
        }

        // Create global wrapper instance
        {
            std::lock_guard<std::mutex> lock(g_wrapper_mutex);
            if (!g_wrapper) {
                g_wrapper = std::make_unique<SpacyWrapper>(model_name);
            }
        }
        return 0;
    } catch (const std::exception& e) {
        std::cerr << "Error initializing Spacy: " << e.what() << std::endl;
        return -1;
    }
}

void spacy_cleanup() {
    std::lock_guard<std::mutex> lock(g_wrapper_mutex);
    g_wrapper.reset();
}

